-- This is an example Hyprland Lua config file.
-- Refer to the wiki for more information.
-- https://wiki.hypr.land/Configuring/Start/

-- Please note not all available settings / options are set here.
-- For a full list, see the wiki

-- You can (and should!!) split this configuration into multiple files
-- Create your files separately and then require them like this:
-- require("myColors")


-- bbkOS generated files (~/.local/state/bbkos/theme/*.lua) are loaded with bbkos_load: a missing file (not generated yet)
-- is skipped, and a broken one runs under pcall so it cannot stop the rest of this config. pcall swallows the error and
-- `hyprctl configerrors` stays empty (checked 2026-10-28), so each failure is shown with Hyprland's own notification and
-- written to ~/.local/state/bbkos/hypr-load-errors (empty when everything loaded), which bbkos-check reads.
local bbkos_state = (os.getenv("HOME") or "") .. "/.local/state/bbkos"
local bbkos_load_errors = {}
local function bbkos_load(name)
    local path = bbkos_state .. "/theme/" .. name
    local f = io.open(path, "r")
    if not f then return end
    f:close()
    local ok, err = pcall(dofile, path)
    if not ok then
        bbkos_load_errors[#bbkos_load_errors + 1] = name .. ": " .. tostring(err)
        hl.notification.create({ text = "bbkOS: " .. name .. " did not load (run bbkos-check)", timeout = 15000 })
    end
end


