hl.config({
    misc = {
        force_default_wallpaper = 0,     -- bbkOS: no mascot wallpapers (no wallpaper daemon until phase 3)
        disable_hyprland_logo   = true,
        background_color        = 0xff101014,
        allow_session_lock_restore = true, -- a fresh hyprlock can take over if the lock client ever crashes
        -- focus_on_activate comes from the Window behaviour page (hypr-theme.lua, on by default: an app that hands you to
        -- another one, like an OAuth sign-in through the browser, is brought forward; the trade-off is that any app may take
        -- focus, so a background app asking while you type could redirect keystrokes; docs/modules/behavior.md).
    },
})

-- Direct scanout stays off (the default): tried on 2026-10-25 with 1 (any fullscreen window) and fullscreen Stremio on
-- battery, it saved nothing measurable (7.86 W off against 7.96 W on, Hyprland 4 % of a core either way, so it most likely
-- never engaged) and it can cause fullscreen flicker on some setups. 2 ("auto") only covers games. docs/modules/power-tuning.md.
hl.config({
    render = {
        direct_scanout = 0,
    },
})


