---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Power key (XF86PowerOff): logind ignores a short press and powers off on a long press (see logind drop-in); a short press opens the menu.
-- No `locked = true`: the menu must not be reachable from the lock screen. The bind itself lives in keybinds.json.
-- Editable binds: generated from ~/.config/bbkos/keybinds.json by bbkos-keybinds (see docs/modules/keybindings.md).
bbkos_load("hypr-binds.lua")

-- The last generated file is loaded: record this load's failures for bbkos-check (an empty file = all loaded).
do
    local path = bbkos_state .. "/hypr-load-errors"
    local f = io.open(path .. ".tmp", "w")
    if f then
        f:write(table.concat(bbkos_load_errors, "\n"), #bbkos_load_errors > 0 and "\n" or "")
        f:close()
        os.rename(path .. ".tmp", path)
    end
end

-- Lid and clamshell handling (logind only looks when the lid closes; see bbkos-lid)
hl.bind("switch:on:Lid Switch",  hl.dsp.exec_cmd("bbkos-lid closed"), { locked = true })
hl.bind("switch:off:Lid Switch", hl.dsp.exec_cmd("bbkos-lid opened"), { locked = true })
hl.on("monitor.removed", function() hl.exec_cmd("bbkos-lid check; bbkos-display apply; qs ipc call display monitorsChanged") end)
hl.on("monitor.added",   function() hl.exec_cmd("bbkos-display apply; qs ipc call display monitorsChanged") end)
-- A monitor moved or resized: no socket event, so the shell is told here (its monitor and window positions go stale otherwise)
hl.on("monitor.layout_changed", function() hl.exec_cmd("qs ipc call display monitorsChanged") end)


