-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- omasnap (screenshots, docs/modules/capture.md): its selection overlay must appear at once, without the layer fade, so the
-- frozen frame lines up with the screen. Do not add no_screen_share here: Hyprland blacks out the whole layer in captures.
hl.layer_rule({
    name = "bbkos-omasnap",
    match = { namespace = "^omasnap$" },
    no_anim = true,
    animation = "none",
})

-- Popups (bbkos-panel) animate their own card in QML: it grows from the widget that was clicked, which the
-- compositor's fade of the full-screen overlay cannot do. Pickers (launcher, clipboard, emoji) are opened from the
-- keyboard many times a day, so they appear at once, like Raycast (docs/modules/motion.md).
hl.layer_rule({
    name = "bbkos-instant-layers",
    match = { namespace = "^(bbkos-panel|bbkos-picker)$" },
    no_anim = true,
    animation = "none",
})

-- bbkos-record's camera overlay (an mpv window, docs/modules/capture.md): floating and on every workspace so it is part of
-- the recording. It can be dragged while recording (drag the video, or Super+drag). bbkos-record places it in a corner and
-- gives the keyboard focus back to the window that had it; no no_focus here, or clicking it would not work either.
hl.window_rule({
    name  = "bbkos-camera",
    match = { class = "^bbkos-camera$" },
    float = true,
    pin = true,
    border_size = 0,
    no_shadow = true,
})

-- Live preview of the Camera settings page (an mpv window started by `bbkos-camera preview`, docs/modules/camera.md):
-- floating; the tool places it beside the settings window.
hl.window_rule({
    name  = "bbkos-camera-preview",
    match = { class = "^bbkos-camera-preview$" },
    float = true,
    no_shadow = true,
})

-- Layer rules also return a handle.
