-- Picture-in-picture (Zen/Firefox "Picture-in-Picture" window): floating, on every workspace, small, top right, no
-- border; without this it is tiled like any window. Same rule as Omarchy's default/hypr/apps/pip.lua.
hl.window_rule({
    name  = "bbkos-pip",
    match = { title = "(Picture.?in.?[Pp]icture)" },
    float = true,
    pin = true,
    size = { 600, 338 },
    keep_aspect_ratio = true,
    border_size = 0,
    move = { "(monitor_w-640)", "(monitor_h*0.04)" },   -- 640 = the 600 px width + 40 px margin: window_w is the size before the size rule here
})

-- Hyprland-run windowrule
-- Terminal UIs opened by bbkos-tui (nmtui, bluetui, ...): floating, centred, a fixed comfortable size.
hl.window_rule({
    name  = "bbkos-tui",
    match = { class = "bbkos-tui-.*" },     -- whole-class match: an anchored ^bbkos-tui- never matches in this version
    float = true,
    size  = "760 480",
    center = true,
})

-- Screen-share picker of xdg-desktop-portal-hyprland (class "hyprland-share-picker", title "Select what to share", read
-- from `hyprctl clients -j`): floating and centred like a dialog instead of a tile that fills the workspace.
hl.window_rule({
    name  = "bbkos-share-picker",
    match = { class = "hyprland-share-picker" },
    float = true,
    size  = "720 480",
    center = true,
})

-- File chooser of xdg-desktop-portal-gtk (open file, save, select folder; every app's "Browse..." button). Class
-- "xdg-desktop-portal-gtk", title "Select folder" / "Open File" / ..., read from `hyprctl clients -j`: it was a tile
-- filling the workspace. The class is only used by this portal's dialogs, so the class alone is enough.
hl.window_rule({
    name  = "bbkos-file-chooser",
    match = { class = "xdg-desktop-portal-gtk" },
    float = true,
    size  = "1000 640",
    center = true,
})

-- Thunar dialogs (rename, properties, create, progress, confirm, open with, preferences): not transient for Hyprland, so
-- they were tiles filling the workspace. Class and titles read from `hyprctl clients -j` with each dialog opened over
-- Thunar's D-Bus API: the class is "thunar" when the daemon starts it and "Thunar" from the launcher, so both are matched;
-- titles look like `a.txt - Properties`, `Rename "a.txt"`, `Create New File`. The file manager window itself
-- ("<folder> - Thunar") is not matched and stays tiled.
hl.window_rule({
    name  = "bbkos-thunar-dialogs",
    match = { class = "[Tt]hunar", title = "^(Rename|File Operation Progress|Create|Properties|Confirm|Open With|Thunar Preferences|Bulk Rename|Replace|Error|Question|Warning|Information|Attention|Empty|Delete|Trash|Move|Copy|Link|Restore|.* - Properties).*" },
    float = true,
    center = true,
})

-- Small GTK helper and about windows that are not transient: zenity's colour chooser ("zenity") and xfce4-about.
hl.window_rule({
    name  = "bbkos-misc-dialogs",
    match = { class = "(zenity|xfce4-about)" },
    float = true,
    center = true,
})

-- bbkOS settings app (Quickshell FloatingWindow). Evidence from `hyprctl clients -j`: class "org.quickshell" (shared by
-- every Quickshell window, so not enough alone), title "bbkOS Settings" (set by the module). Whole-string matches.
hl.window_rule({
    name  = "bbkos-settings",
    match = { class = "org\\.quickshell", title = "bbkOS Settings" },
    float = false,     -- tiled: fills the workspace like any other app (owner's choice 2026-10-28; was floating 1120x720)
})

-- Android apps window (Quickshell FloatingWindow, docs/modules/android.md): class "org.quickshell" + title "bbkOS Android".
hl.window_rule({
    name  = "bbkos-android",
    match = { class = "org\\.quickshell", title = "bbkOS Android" },
    float = true,
    size  = "960 680",
    center = true,
})

hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})
